#define _CRT_SECURE_NO_WARNINGS
#include <assert.h>
#include <stdio.h>
#include "../src/part_command.h"
int main(void){
    const wchar_t *valid[]={
        L"SKETCH_CREATE PRT1 S1 PLANE:FRONT PLANE:RIGHT ELLIPSE 0 0 24 8 31",
        L"SKETCH_ADD PRT1 S1 SLOT 0 0 30 8 -27",L"SKETCH_ADD PRT1 S1 POLYGON 16 0 0 SIDE 10 0",
        L"SKETCH_ADD PRT1 S1 SPLINE THROUGH 0 0 2 4 9 2",L"SKETCH_ADD PRT1 S1 SPLINE CONTROL 0 0 2 4 9 2",
        L"SKETCH_OFFSET PRT1 S1 -2 0 1 2 3",L"SKETCH_MIRROR PRT1 S1 4 0 1 2 3",
        L"SKETCH_TRIM_EXTEND PRT1 S1 EXTEND START 3 4",L"SKETCH_CORNER PRT1 S1 ROUND 2 0 1",
        L"SKETCH_PROJECT_CHAIN PRT1 S1 EDGE:12 EDGE:13",L"SKETCH_PROJECT_CHAIN PRT1 S1 CURVE:CHAIN",
        L"SKETCH_CHECK PRT1 S1",L"SKETCH_REPAIR PRT1 S1 0.1",
        L"REFERENCES PRT1",L"REFERENCES PRT1 SURFACE:2",L"REFERENCES PRT1 EDGE:71",
        L"DATUM_PLANE PRT1 DTM1 PLANE:TOP -25",L"DATUM_AXIS PRT1 A1 PLANES TOP RIGHT",L"DATUM_AXIS PRT1 A1 CYLINDER SURFACE:70",
        L"DATUM_POINT PRT1 P1 CSYS:PRT_CSYS 1 2 3",L"DATUM_CSYS PRT1 C1 CSYS:PRT_CSYS 1 2 3 90 0 -45",L"DATUM_CURVE PRT1 L1 CSYS:PRT_CSYS 0 0 0 10 20 30",
        L"DATUM_PLANE_ANGLE PRT1 D1 PLANE:RIGHT AXIS:A1 -25",L"DATUM_PLANE_ANGLE PRT1 D1 SURFACE:15 EDGE:13 35",
        L"DATUM_PLANE_3POINT PRT1 D1 POINT:P1 POINT:P2 POINT:P3",L"DATUM_PLANE_MID PRT1 D1 PLANE:RIGHT SURFACE:15",
        L"DATUM_PLANE_TANGENT PRT1 D1 SURFACE:15 POINT:P1",L"DATUM_PLANE_NORMAL PRT1 D1 CURVE:C1 POINT:P1",
        L"DATUM_AXIS_2POINT PRT1 A1 POINT:P1 POINT:P2",L"DATUM_POINT_CURVE PRT1 P1 CURVE:C1 PERCENT 25",
        L"DATUM_POINT_CURVE PRT1 P1 CURVE:C1 START 0",L"DATUM_CURVE_INTERSECT PRT1 C1 SURFACE:15 PLANE:RIGHT",
        L"DATUM_CURVE_SPLINE PRT1 C1 CSYS:C0 0 0 0 10 4 8 20 18 -4",L"DATUM_CSYS_SYM PRT1 C1 PLANE:RIGHT PLANE:TOP PLANE:FRONT POS NEG",
        L"SKETCH_BEGIN PRT1 SK1 TOP RIGHT",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT RECT -40 -30 80 60",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT CIRCLE 0 0 5",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT LINE 0 0 20 20",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT ARC 0 0 10 0 90",
        L"SKETCH_ADD PRT1 SK1 LINE 0 0 10 10",L"SKETCH_ADD PRT1 SK1 CENTERLINE 0 0 10 0",L"SKETCH_INFO PRT1 SK1",
        L"SKETCH_DIM PRT1 SK1 LENGTH 0 NONE 20",L"SKETCH_DIM PRT1 SK1 RADIUS 0 NONE 20",L"SKETCH_DIM PRT1 SK1 DIAMETER 0 NONE 20",L"SKETCH_DIM PRT1 SK1 ANGLE 0 1 45",L"SKETCH_DIM PRT1 SK1 DISTANCE 0:START 0:END 10",L"SKETCH_DIM PRT1 SK1 DISTANCE_X 0:CENTER 1:CENTER 30",L"SKETCH_DIM PRT1 SK1 DISTANCE_Y 0:END 1:START 5",
        L"SKETCH_CONSTRAINT PRT1 SK1 HORIZONTAL 0",L"SKETCH_CONSTRAINT PRT1 SK1 VERTICAL 0",L"SKETCH_CONSTRAINT PRT1 SK1 COINCIDENT 0:END 1:START",L"SKETCH_CONSTRAINT PRT1 SK1 PARALLEL 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 PERPENDICULAR 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 TANGENT 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 EQUAL_LENGTH 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 EQUAL_RADIUS 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 SYMMETRY 0:START 1:START 2"
    };
    const wchar_t *invalid[]={
        L"SKETCH_ADD PRT1 S1 ELLIPSE 0 0 8 24 0",L"SKETCH_ADD PRT1 S1 SLOT 0 0 8 8 0",
        L"SKETCH_ADD PRT1 S1 POLYGON 2 0 0 SIDE 10 0",L"SKETCH_ADD PRT1 S1 POLYGON 6 0 0 SIDE 0 0",
        L"SKETCH_ADD PRT1 S1 SPLINE THROUGH 0 0 2 4",L"SKETCH_ADD PRT1 S1 SPLINE CONTROL 0 0 2 4 9",
        L"SKETCH_OFFSET PRT1 S1 0 0",L"SKETCH_OFFSET PRT1 S1 2 0 00",
        L"SKETCH_MIRROR PRT1 S1 4 4",L"SKETCH_TRIM_EXTEND PRT1 S1 TRIM WHOLE 3 4",
        L"SKETCH_CORNER PRT1 S1 CHAMFER 2 0 0",L"SKETCH_PROJECT_CHAIN PRT1 S1 EDGE:12 EDGE:012",
        L"SKETCH_PROJECT_CHAIN PRT1 S1 CURVE:C1 CURVE:C2",L"SKETCH_REPAIR PRT1 S1 0.251",
        L"DATUM_PLANE_ANGLE PRT1 D1 PLANE:RIGHT AXIS:A1 180",L"DATUM_PLANE_ANGLE PRT1 D1 PLANE:RIGHT POINT:P1 30",
        L"DATUM_PLANE_3POINT PRT1 D1 POINT:P1 POINT:P2",L"DATUM_PLANE_MID PRT1 D1 PLANE:RIGHT PLANE:RIGHT",
        L"DATUM_PLANE_TANGENT PRT1 D1 PLANE:RIGHT POINT:P1",L"DATUM_PLANE_NORMAL PRT1 D1 CURVE:C1 AXIS:A1",
        L"DATUM_AXIS_2POINT PRT1 A1 POINT:P1 POINT:P1",L"DATUM_POINT_CURVE PRT1 P1 CURVE:C1 PERCENT 101",
        L"DATUM_POINT_CURVE PRT1 P1 CURVE:C1 START 1",L"DATUM_CURVE_INTERSECT PRT1 C1 SURFACE:15 SURFACE:15",
        L"DATUM_CURVE_SPLINE PRT1 C1 CSYS:C0 0 0 0 10 4 8 20 18",L"DATUM_CSYS_SYM PRT1 C1 PLANE:RIGHT PLANE:TOP PLANE:FRONT POS FLIP",
        L"DATUM_PLANE PRT1 DTM1 TOP nan",L"DATUM_PLANE PRT1 DTM1 TOP 0",L"DATUM_POINT PRT1 P1 C1 0 1",L"DATUM_CSYS PRT1 C1 C0 0 0 0 361 0 0",L"DATUM_CURVE PRT1 L1 C0 1 2 3 1 2 3",L"DATUM_AXIS PRT1 A1 PLANES TOP TOP",L"REFERENCES PRT1 SURFACE:-1",L"DATUM_POINT PRT1 ../p C0 1 2 3",L"SKETCH_CREATE PRT1 SK1 TOP RIGHT RECT 0 0 -1 10",L"SKETCH_ADD PRT1 SK1 LINE 0 0 0 0",L"SKETCH_ADD PRT1 SK1 ARC 0 0 5 0 360",L"SKETCH_DIM PRT1 SK1 LENGTH 0 NONE inf",L"SKETCH_DIM PRT1 SK1 ANGLE 0 1 361",L"SKETCH_DIM PRT1 SK1 DISTANCE 0 0 10",L"SKETCH_DIM PRT1 SK1 LENGTH 0 1 10",L"SKETCH_CONSTRAINT PRT1 SK1 HORIZONTAL 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 SYMMETRY 0 1",L"SKETCH_CONSTRAINT PRT1 SK1 TANGENT 0:BAD 1"
    };
    wchar_t protocol[1024];PartCommand cmd;int i;
    for(i=0;i<sizeof(valid)/sizeof(valid[0]);i++){swprintf_s(protocol,1024,L"CREO_OP %ls",valid[i]);assert(part_command_parse(protocol,&cmd)==1&&cmd.verb==PART_FOUNDATION);}
    for(i=0;i<sizeof(invalid)/sizeof(invalid[0]);i++){swprintf_s(protocol,1024,L"CREO_OP %ls",invalid[i]);assert(part_command_parse(protocol,&cmd)==-1&&cmd.verb==PART_NONE);}
    assert(part_command_parse(L"CREO_OP REFERENCES PRT1\nCREO_OP DATUM_PLANE PRT1 P1 TOP 5",&cmd)==-1);
    assert(part_command_parse(L"CREO_OP SKETCH_ADD PRT1 SK1 CIRCLE 0 0 5\nCREO_PLAN EMPTY_SOLID",&cmd)==-1);
    assert(part_command_parse(L"CREO_OP SOLID_DRAFT PRT1 DRAFT_1 SURFACE:103 SURFACE:91 PLANE:FRONT 5 POS",&cmd)==1);
    assert(part_command_parse(L"CREO_OP SOLID_RIB PRT1 RIB_1 WEB_SK 4 NEG SYM",&cmd)==1);
    assert(part_command_parse(L"CREO_OP FEATURE_MIRROR PRT1 MIRROR_1 HOLE_1 PLANE:MID",&cmd)==1);
    assert(part_command_parse(L"CREO_OP FEATURE_PATTERN_LINEAR PRT1 PAT_1 HOLE_1 PLANE:RIGHT 3 15 NEG",&cmd)==1);
    assert(part_command_parse(L"CREO_OP FEATURE_PATTERN_CIRCULAR PRT1 PAT_2 HOLE_1 AXIS:AX_1 4 90 POS",&cmd)==1);
    assert(part_command_parse(L"CREO_OP FEATURE_DELETE PRT1 HOLE_1 FEATURE:115",&cmd)==1);
    assert(part_command_parse(L"CREO_OP SOLID_DRAFT PRT1 DRAFT_1 SURFACE:103 SURFACE:91 PLANE:FRONT 35 POS",&cmd)==-1);
    assert(part_command_parse(L"CREO_OP SOLID_RIB PRT1 RIB_1 WEB_SK 4 NEG INSIDE",&cmd)==-1);
    assert(part_command_parse(L"CREO_OP FEATURE_MIRROR PRT1 MIRROR_1 HOLE_1 AXIS:A1",&cmd)==-1);
    assert(part_command_parse(L"CREO_OP FEATURE_PATTERN_LINEAR PRT1 PAT_1 HOLE_1 PLANE:RIGHT 21 15 NEG",&cmd)==-1);
    assert(part_command_parse(L"CREO_OP FEATURE_PATTERN_CIRCULAR PRT1 PAT_2 HOLE_1 AXIS:AX_1 5 90 POS",&cmd)==-1);
    assert(part_command_parse(L"CREO_OP FEATURE_DELETE PRT1 HOLE_1 FEATURE:0",&cmd)==-1);
    printf("foundation protocol: %d valid + %d invalid + 2 mixed-command cases passed\n",(int)(sizeof(valid)/sizeof(valid[0])),(int)(sizeof(invalid)/sizeof(invalid[0])));return 0;
}
